using System.Text.Json;
using VisionCore;
using VisionEditor.Core;
using VisionFramework;
using VisionModules;

static class GroupIndexCompoundChecks
{
 public static async Task Run(ModuleRegistry registry,Action<bool,string,object?> check)
 {
  var arrayDescriptor=new ModuleDescriptor("checks.index-source","1","索引源",[],[new("array",DataKind.Integer){Cardinality=ValueCardinality.Array},new("index",DataKind.Integer),new("floatArray",DataKind.Number){Cardinality=ValueCardinality.Array}], [new("Index",ParameterKind.Integer,false,JsonSerializer.SerializeToElement(1))]);
  registry.Register(arrayDescriptor,()=>new IndexSource(arrayDescriptor));
  var doc=new GraphEditorDocument(registry);var root=doc.CurrentProcedureId;var upstream=doc.AddNode(arrayDescriptor.Id,"1",100,100);var group=doc.AddOwnedGroup(100,250);doc.ConnectExecution(upstream,group);var body=doc.EnterOwnedGroup(group);doc.LeaveGroup();
  doc.SetParameter(group,"EnableLoop",JsonSerializer.SerializeToElement(true));doc.SetParameter(group,"EndIndex",JsonSerializer.SerializeToElement(4));
  var arrayOperand=new GroupOperand(false,new(WorkflowSourceKind.NodeOutput,upstream,"array")){IndexSource=new(WorkflowSourceKind.NodeOutput,upstream,"index")};
  doc.SetGroupBreak(group,true,1,5,new(new(true,new(WorkflowSourceKind.GroupLoopIndex,"LoopIndex")),arrayOperand));var executor=new SolutionExecutor(registry);
  async Task<ExecutionSessionResult> Run()=>await executor.RunAsync(new(doc.Document,doc.BaseDirectory),root);
  var result=await Run();check(result.Status==SessionStatus.Success&&result.Calls[group].GroupBreakIndex==1&&result.Calls[group].CompletedGroupIterations==1,"Dynamic array index resolves preceding current-run integer and breaks at selected element1",null);
  doc.SetParameter(upstream,"Index",JsonSerializer.SerializeToElement(2));result=await Run();check(result.Calls[group].GroupBreakIndex==2&&result.Calls[group].CompletedGroupIterations==2,"Changing actual upstream index changes next invocation; old selected element is not captured persistently",null);
  doc.SetParameter(upstream,"Index",JsonSerializer.SerializeToElement(10));result=await Run();check(!result.Calls[group].GroupBroke&&result.Calls[group].CompletedGroupIterations==4&&result.Calls[group].GroupDiagnostics.Count>0,"Out-of-range dynamic index does not use stale successful comparison",result.Calls[group].GroupDiagnostics);
  doc.SetParameter(upstream,"Index",JsonSerializer.SerializeToElement(-1));result=await Run();check(!result.Calls[group].GroupBroke&&result.Calls[group].GroupDiagnostics.Any(s=>s.Contains("nonnegative")),"Negative dynamic index is diagnosed without unsigned wrap or false break",null);
  doc.SetParameter(upstream,"Index",JsonSerializer.SerializeToElement(2));var path=Path.GetFullPath("analysis/full-audit/group-dynamic-index.vmx.json");doc.Save(path);var loaded=new GraphEditorDocument(registry);loaded.Load(path);result=await executor.RunAsync(new(loaded.Document,loaded.BaseDirectory),root);check(result.Calls[group].GroupBreakIndex==2,"Dynamic index binding survives save reopen and actual execution",null);
  var pasted=doc.PasteNodes(doc.CopyNodes([upstream,group]),400,100);var copiedSource=pasted.Single(id=>doc.CurrentProcedure.Nodes.Single(n=>n.Id==id).ModuleId==arrayDescriptor.Id);var copiedGroup=pasted.Single(id=>id!=copiedSource);check(doc.CurrentProcedure.Nodes.Single(n=>n.Id==copiedGroup).GroupBreak!.Right!.IndexSource!.Id==copiedSource,"Clipboard remaps dynamic index identity as well as array source",null);result=await Run();check(result.Calls[copiedGroup].GroupBreakIndex==2,"Copied dynamic-index dependency executes independently",null);
  doc.DeleteNode(copiedSource);check(doc.CurrentProcedure.Nodes.Single(n=>n.Id==copiedGroup).GroupBreak!.Right is null,"Deleting index producer removes stale comparison binding rather than silently reverting to element0",null);doc.Undo();check(doc.CurrentProcedure.Nodes.Single(n=>n.Id==copiedGroup).GroupBreak!.Right!.IndexSource!.Id==copiedSource,"Undo restores exact dynamic index dependency",null);
  var projectDescriptor=new ModuleDescriptor("checks.geometry-fields","1","几何字段投影",[new("circle",DataKind.Circle)],[new("point",DataKind.Point),new("fixture",DataKind.Fixture)],[]);registry.Register(projectDescriptor,()=>new GeometryFields(projectDescriptor));
  doc.DeleteNode(copiedGroup);doc.DeleteNode(copiedSource);
  var indexOnly=doc.AddNode(arrayDescriptor.Id,"1",300,100);doc.ConnectExecution(indexOnly,group);var primary=new GroupOperand(false,new(WorkflowSourceKind.NodeOutput,upstream,"array")){IndexSource=new(WorkflowSourceKind.NodeOutput,indexOnly,"index")};doc.SetGroupBreak(group,true,1,5,new(new(true,new(WorkflowSourceKind.GroupLoopIndex,"LoopIndex")),primary));
  doc.DeleteNode(indexOnly);check(doc.CurrentProcedure.Nodes.Single(n=>n.Id==group).GroupBreak!.Right is null&&doc.CurrentProcedure.Nodes.Any(n=>n.Id==upstream),"Deleting only index producer clears binding while retaining independent array producer",null);doc.Undo();
  var revision=doc.Revision;bool rejected=false;try{doc.SetGroupBreak(group,true,1,5,new(new(true,new(WorkflowSourceKind.GroupLoopIndex,"LoopIndex")),primary with{IndexSource=new(WorkflowSourceKind.NodeOutput,upstream,"array")}));}catch(InvalidDataException){rejected=true;}check(rejected&&doc.Revision==revision,"Array-valued index source is rejected atomically; only scalar integer references allowed",null);
  doc.SetGroupBreak(group,true,1,5,new(new(true,new(WorkflowSourceKind.GroupLoopIndex,"LoopIndex")),arrayOperand));
  var isolated=await new GroupDebugExecutor(registry).RunAsync(new(doc.Document,doc.BaseDirectory),root,group);
  check(isolated.Calls[group].CompletedGroupIterations==4&&!isolated.Calls[group].GroupBroke&&isolated.Calls[group].GroupDiagnostics.Count>0,"Group SelfRun missing current index data diagnoses without reading previous parent run or invoking upstream",null);
  doc.SetParameter(upstream,"Index",JsonSerializer.SerializeToElement(1));doc.SetGroupBreak(group,true,2,3,new(new(Constant:JsonSerializer.SerializeToElement(1d)),new GroupOperand(false,new(WorkflowSourceKind.NodeOutput,upstream,"floatArray")){IndexSource=new(WorkflowSourceKind.NodeOutput,upstream,"index")}));
  result=await Run();check(result.Status==SessionStatus.Success&&result.Calls[group].GroupBroke&&result.Calls[group].GroupBreakIndex==0,"Float comparison array uses integer index dependency without confusing comparison kind with index kind",null);
  var geometry=new GraphEditorDocument(registry);var geometryRoot=geometry.CurrentProcedureId;var outer=geometry.AddOwnedGroup(100,100);var outerBody=geometry.EnterOwnedGroup(outer);var inner=geometry.AddOwnedGroup(100,100);var innerBody=geometry.EnterOwnedGroup(inner);
  var source=geometry.AddNode("vision.image-file","1.0.0",100,100,new(){["Path"]=JsonSerializer.SerializeToElement(Path.GetFullPath("analysis/images/circle-find-sample.bmp"))});
  var circle=geometry.AddNode("vision.circle","1.0.0",100,200,new(){["CenterX"]=J(717d),["CenterY"]=J(507d),["InitialRadius"]=J(375d),["SearchHalfWidth"]=J(12d),["SampleCount"]=J(64),["GradientThreshold"]=J(15d),["Polarity"]=J("Both"),["RadialStep"]=J(.5d),["GradientHalfSpan"]=J(1d),["MinimumEdges"]=J(20)});geometry.Connect(source,"Image",circle,"Image");
  var projection=geometry.AddNode(projectDescriptor.Id,"1",300,300);geometry.Connect(circle,"Circle",projection,"circle");
  geometry.SetWorkflowConfiguration(innerBody,new(){Outputs=[new("circle","circle",DataKind.Circle,circle,"Circle",Accumulate:true),new("point","point",DataKind.Point,projection,"point",Accumulate:true),new("fixture","fixture",DataKind.Fixture,projection,"fixture",Accumulate:true),new("radius","radius",DataKind.Number,circle,"Radius",Accumulate:true),new("image","image",DataKind.GrayImage,source,"Image",Accumulate:true)]});geometry.LeaveGroup();geometry.SetParameter(inner,"EnableLoop",J(true));geometry.SetParameter(inner,"EndIndex",J(3));geometry.SetWorkflowConfiguration(outerBody,new(){Outputs=[new("circle","circle",DataKind.Circle,inner,"circle",Accumulate:true){Cardinality=ValueCardinality.Array},new("point","point",DataKind.Point,inner,"point",Accumulate:true){Cardinality=ValueCardinality.Array},new("fixture","fixture",DataKind.Fixture,inner,"fixture",Accumulate:true){Cardinality=ValueCardinality.Array},new("radius","radius",DataKind.Number,inner,"radius",Accumulate:true){Cardinality=ValueCardinality.Array},new("image","image",DataKind.GrayImage,inner,"image",Accumulate:true)]});geometry.LeaveGroup();geometry.SetParameter(outer,"EnableLoop",J(true));geometry.SetParameter(outer,"EndIndex",J(2));
  var real=await executor.RunAsync(new(geometry.Document,geometry.BaseDirectory),geometryRoot);var actual=real.Calls[outer];
  check(real.Status==SessionStatus.Success&&actual.WorkflowOutputs["circle"].Cardinality==ValueCardinality.Array&&actual.WorkflowOutputs["circle"].ElementCount==6,"Two nested Groups flatten six actual radial-circle algorithm results into compound array",null);
  var circles=actual.WorkflowOutputs["circle"].As<IReadOnlyList<CircleFit>>();check(circles.All(c=>c.Radius>370&&c.Radius<385)&&actual.WorkflowOutputs["radius"].As<IReadOnlyList<double>>().SequenceEqual(circles.Select(c=>c.Radius)),"Compound fields remain aligned with corresponding numeric leaf arrays from real image results",circles.Select(c=>c.Radius).ToArray());
  check(actual.WorkflowOutputs["image"].Cardinality==ValueCardinality.Scalar&&actual.WorkflowOutputs["image"].As<GrayImage>().Width==1296,"Image accumulation toggle still replaces with final image instead of inventing image array",null);
  var points=actual.WorkflowOutputs["point"];var fixtures=actual.WorkflowOutputs["fixture"];
  check(points.ElementCount==6&&fixtures.ElementCount==6&&points.Element(3).As<Point2>().X==circles[3].CenterX&&fixtures.Element(3).As<FixtureValue>().Run.Y==circles[3].CenterY,"Point and Fixture fields from real circle projection cross two actual Group call boundaries",null);
  check(PortValue.JoinArray(DataKind.Point,new[]{points,points}).ElementCount==12&&PortValue.JoinArray(DataKind.Fixture,new[]{fixtures,fixtures}).Element(7).As<FixtureValue>().Run.X==circles[1].CenterX,"Point and Fixture typed compound arrays flatten nested blocks without losing geometry fields",null);
  path=Path.GetFullPath("analysis/full-audit/group-compound-real.vmx.json");geometry.Save(path);loaded=new(registry);loaded.Load(path);var again=await executor.RunAsync(new(loaded.Document,loaded.BaseDirectory),geometryRoot);check(again.Status==SessionStatus.Success&&again.Calls[outer].WorkflowOutputs["circle"].As<IReadOnlyList<CircleFit>>().SequenceEqual(circles),"Nested compound output signature and actual algorithm results survive save reopen",null);
  geometry.EnterOwnedGroup(outer);geometry.EnterOwnedGroup(inner);geometry.SetWorkflowConfiguration(innerBody,geometry.CurrentProcedure.Configuration with{Outputs=geometry.CurrentProcedure.Configuration.Outputs.Select(o=>o.Id=="circle"?o with{Accumulate=false}:o).ToArray()});
  check(geometry.Document.Procedures.Single(p=>p.Id==outerBody).Nodes.Single(n=>n.Id==inner).Call!.Outputs.Single(o=>o.Name=="circle").Cardinality==ValueCardinality.Scalar,"Turning compound accumulation off updates actual owned-call signature",null);
  var finalScalar=await executor.RunAsync(new(geometry.Document,geometry.BaseDirectory),geometryRoot);check(finalScalar.Status==SessionStatus.Success&&finalScalar.Calls[outer].WorkflowOutputs["circle"].ElementCount==2,"Disabling inner compound accumulation changes actual outer runtime from six elements to two fresh final-round circles",null);
  static JsonElement J<T>(T value)=>JsonSerializer.SerializeToElement(value);
 }
 sealed class GeometryFields(ModuleDescriptor descriptor):IModule{public ModuleDescriptor Descriptor=>descriptor;public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext context,CancellationToken token){var c=context.Input<CircleFit>("circle");return ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>{{"point",PortValue.Point(new(c.CenterX,c.CenterY))},{"fixture",PortValue.Fixture(new(new(),new(c.CenterX,c.CenterY,0)))}}));}}
 sealed class IndexSource(ModuleDescriptor descriptor):IModule{public ModuleDescriptor Descriptor=>descriptor;public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext context,CancellationToken token)=>ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>{{"array",PortValue.IntegerArray(new long[]{0,1,2})},{"index",PortValue.Integer(context.Integer("Index"))},{"floatArray",PortValue.NumberArray(new double[]{0,1,2})}}));}
}
